7.    * @param subtotalCents Sum of (unitPriceCents * quantity) across all lines, before any discount.
8.    * @returns Discount amount in cents as an integer. Cart.totals() clamps the returned value
9.    *          into [0, subtotalCents], so policies should aim for that range but are not
10.    *          required to — negative values are clamped to 0 and over-subtotal values are
11.    *          clamped down to subtotalCents.
12.    */
13.   computeDiscountCents(subtotalCents: number): number;
14. }
