describe("CompositeDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects empty policy list", () => {
      expect(() => new CompositeDiscountPolicy([])).toThrow(
        "CompositeDiscountPolicy requires at least one policy",
      );
    });
  });

  describe("sum mode", () => {
    it("sums discounts from all policies against original subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10), // 100
          new FixedAmountDiscountPolicy(200), // 200
        ],
        "sum",
      );
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(-100)).toBe(0);
    });

    it("defaults to sum mode when not specified", () => {
      const composite = new CompositeDiscountPolicy([
        new PercentageDiscountPolicy(10),
        new FixedAmountDiscountPolicy(200),
      ]);
      // sum mode: both compute against original 1000
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("can exceed subtotal (caller clamps)", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(100), // 1000
          new FixedAmountDiscountPolicy(500), // 500
        ],
        "sum",
      );
      // sum = 1500, exceeds subtotal — the composite itself doesn't clamp
      expect(composite.computeDiscountCents(1000)).toBe(1500);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially on remaining subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10), // 10% of 1000 = 100, remaining 900
          new FixedAmountDiscountPolicy(200), // min(200, 900) = 200
        ],
        "chain",
      );
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("second policy sees reduced subtotal in chain", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(50), // 50% of 1000 = 500, remaining 500
          new PercentageDiscountPolicy(50), // 50% of 500 = 250, remaining 250
        ],
        "chain",
      );
      expect(composite.computeDiscountCents(1000)).toBe(750);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("chain cannot exceed subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new FixedAmountDiscountPolicy(600), // min(600, 1000) = 600, remaining 400
          new FixedAmountDiscountPolicy(600), // min(600, 400) = 400, remaining 0
        ],
        "chain",
      );
      expect(composite.computeDiscountCents(1000)).toBe(1000);
    });

    it("ordering matters in chain mode", () => {
      // Order 1: fixed first, then percentage
      const c1 = new CompositeDiscountPolicy(
        [
          new FixedAmountDiscountPolicy(200), // 200 off 1000 → remaining 800
          new PercentageDiscountPolicy(10), // 10% of 800 = 80
        ],
        "chain",
      );
      // Order 2: percentage first, then fixed
      const c2 = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10), // 10% of 1000 = 100 → remaining 900
          new FixedAmountDiscountPolicy(200), // 200 off 900 → 200
        ],
        "chain",
      );
      expect(c1.computeDiscountCents(1000)).toBe(280);
      expect(c2.computeDiscountCents(1000)).toBe(300);
    });
  });
});

