        computeShippingCents: vi.fn().mockReturnValue(500),
      };

      const cart = new Cart({ discountPolicy, taxCalculator, shippingCalculator });
      cart.add(makeProduct("a", 1000), 1); // subtotal = 1000

      const totals = cart.totals();

      expect(totals.subtotalCents).toBe(1000);
      expect(totals.discountCents).toBe(200);
      // Tax is computed on discounted subtotal (1000 - 200 = 800)
      expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(800, "US");
      expect(totals.taxCents).toBe(80);
      // Shipping gets discounted subtotal
      expect(shippingCalculator.computeShippingCents).toHaveBeenCalledWith(
        expect.any(Array),
        800,
      );
      expect(totals.shippingCents).toBe(500);
      // total = discountedSubtotal + tax + shipping = 800 + 80 + 500
      expect(totals.totalCents).toBe(1380);
