      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const invErr = err as InventoryError;
        expect(invErr.message).toBe("discontinued");
        expect(invErr.productId).toBe("prod-1");
        expect(invErr.requested).toBe(2);
      }
    });

    it("throws InventoryError for partial-stock denial", async () => {
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: true,
          availableQuantity: 1, // only 1 available but 2 requested
        }),
      };
      try {
        await cart.checkout({ inventoryChecker });
        expect.unreachable("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const invErr = err as InventoryError;
        expect(invErr.productId).toBe("prod-1");
        expect(invErr.requested).toBe(2);
        expect(invErr.available).toBe(1);
      }
    });

    it("generates default message for unavailable without reason", async () => {
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: false }),
      };
      try {
        await cart.checkout({ inventoryChecker });
        expect.unreachable("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        expect((err as InventoryError).message).toContain("insufficient stock");
      }
    });

    it("passes inventory check when all items are available", async () => {
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 100 }),
      };
      const result = await cart.checkout({ inventoryChecker });
      expect(result.totals.subtotalCents).toBe(2500);
      expect(inventoryChecker.check).toHaveBeenCalledTimes(2);
    });

    it("uses asyncTaxProvider for tax calculation", async () => {
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1), // 10%
      };
      const result = await cart.checkout({ asyncTaxProvider });
      // subtotal = 2500, no discount, tax = floor(2500 * 0.1) = 250
      expect(result.totals.taxCents).toBe(250);
      expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US");
    });

    it("uses asyncTaxProvider with discount applied", async () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(500),
      };
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };
      const discountedCart = new Cart({ discountPolicy });
      discountedCart.add(makeProduct("prod-1", 1000), 2);
      discountedCart.add(makeProduct("prod-2", 500), 1);

      const result = await discountedCart.checkout({ asyncTaxProvider });
      // subtotal = 2500, discount = 500, discounted = 2000
      // tax = floor(2000 * 0.1) = 200
      expect(result.totals.discountCents).toBe(500);
      expect(result.totals.taxCents).toBe(200);
    });

    it("combines priceFetcher, inventoryChecker, and asyncTaxProvider", async () => {
      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(1000),
      };
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 50 }),
      };
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.05),
      };
      const result = await cart.checkout({
        priceFetcher,
        inventoryChecker,
        asyncTaxProvider,
      });
      // prices refreshed to 1000 each: subtotal = 1000*2 + 1000*1 = 3000
      // tax = floor(3000 * 0.05) = 150
      expect(result.totals.subtotalCents).toBe(3000);
      expect(result.totals.taxCents).toBe(150);
      expect(result.totals.totalCents).toBe(3150);
    });

    it("propagates priceFetcher rejection", async () => {
      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockRejectedValue(new Error("price service down")),
      };
      await expect(cart.checkout({ priceFetcher })).rejects.toThrow("price service down");
    });

    it("propagates asyncTaxProvider rejection", async () => {
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
      };
      await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow("tax service down");
    });

    it("checkout with shipping calculator", async () => {
      const shippingCalculator: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(750),
      };
      const shippedCart = new Cart({ shippingCalculator });
      shippedCart.add(makeProduct("x", 2000), 1);
      const result = await shippedCart.checkout();
      expect(result.totals.shippingCents).toBe(750);
      expect(result.totals.totalCents).toBe(2750); // 2000 + 0 tax + 750 shipping
    });

    it("checkout on empty cart succeeds with zero totals", async () => {
      const emptyCart = new Cart();
      const result = await emptyCart.checkout();
      expect(result.totals.totalCents).toBe(0);
      expect(result.lines).toHaveLength(0);
    });
  });
});

import { describe, it, expect } from "vitest";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
  CompositeDiscountPolicy,
} from "../src/pricing.ts";

describe("NoDiscountPolicy", () => {
  const policy = new NoDiscountPolicy();

  it.each([
    [0, 0],
    [1000, 0],
    [999999, 0],
    [-500, 0],
  ])("computeDiscountCents(%i) returns %i", (subtotal, expected) => {
    expect(policy.computeDiscountCents(subtotal)).toBe(expected);
  });
});

describe("PercentageDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([
      [-1, "percent must be between 0 and 100"],
      [101, "percent must be between 0 and 100"],
      [NaN, "percent must be between 0 and 100"],
      [Infinity, "percent must be between 0 and 100"],
    ])("rejects invalid percent %s", (percent, message) => {
      expect(() => new PercentageDiscountPolicy(percent)).toThrow(RangeError);
      expect(() => new PercentageDiscountPolicy(percent)).toThrow(message);
    });

    it.each([0, 50, 100])("accepts valid percent %i", (percent) => {
      expect(() => new PercentageDiscountPolicy(percent)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("returns 0 for zero subtotal", () => {
      const policy = new PercentageDiscountPolicy(10);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new PercentageDiscountPolicy(10);
      expect(policy.computeDiscountCents(-500)).toBe(0);
    });

    it("computes 10% of 1000 cents", () => {
      const policy = new PercentageDiscountPolicy(10);
      expect(policy.computeDiscountCents(1000)).toBe(100);
    });

    it("floors fractional cents (10% of 1001 = 100.1 → 100)", () => {
      const policy = new PercentageDiscountPolicy(10);
      expect(policy.computeDiscountCents(1001)).toBe(100);
    });

    it("100% returns full subtotal", () => {
      const policy = new PercentageDiscountPolicy(100);
      expect(policy.computeDiscountCents(5000)).toBe(5000);
    });

    it("0% returns 0", () => {
      const policy = new PercentageDiscountPolicy(0);
      expect(policy.computeDiscountCents(5000)).toBe(0);
    });

    it("handles fractional percent (33.33%)", () => {
      const policy = new PercentageDiscountPolicy(33.33);
      // 10000 * 33.33 / 100 = 3333
      expect(policy.computeDiscountCents(10000)).toBe(3333);
    });
  });
});

describe("FixedAmountDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects negative amount", () => {
      expect(() => new FixedAmountDiscountPolicy(-1)).toThrow(RangeError);
    });

    it("rejects non-integer amount", () => {
      expect(() => new FixedAmountDiscountPolicy(10.5)).toThrow(RangeError);
    });

    it("accepts zero", () => {
      expect(() => new FixedAmountDiscountPolicy(0)).not.toThrow();
    });

    it("accepts positive integer", () => {
      expect(() => new FixedAmountDiscountPolicy(500)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("returns 0 for zero subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(-100)).toBe(0);
    });

    it("returns full discount when subtotal exceeds amount", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(1000)).toBe(500);
    });

    it("clamps to subtotal when discount exceeds subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(300)).toBe(300);
    });

    it("returns subtotal when discount equals subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(1000);
      expect(policy.computeDiscountCents(1000)).toBe(1000);
    });
  });
});

describe("CompositeDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects empty policy list", () => {
      expect(() => new CompositeDiscountPolicy([])).toThrow(
        "CompositeDiscountPolicy requires at least one policy",
      );
    });
  });

  describe("sum mode", () => {
    it("sums discounts from all policies against original subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10), // 100
          new FixedAmountDiscountPolicy(200), // 200
        ],
        "sum",
      );
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(-100)).toBe(0);
    });

    it("defaults to sum mode when not specified", () => {
      const composite = new CompositeDiscountPolicy([
        new PercentageDiscountPolicy(10),
        new FixedAmountDiscountPolicy(200),
      ]);
      // sum mode: both compute against original 1000
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("can exceed subtotal (caller clamps)", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(100), // 1000
          new FixedAmountDiscountPolicy(500), // 500
        ],
        "sum",
      );
      // sum = 1500, exceeds subtotal — the composite itself doesn't clamp
      expect(composite.computeDiscountCents(1000)).toBe(1500);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially on remaining subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10), // 10% of 1000 = 100, remaining 900
          new FixedAmountDiscountPolicy(200), // min(200, 900) = 200
        ],
        "chain",
      );
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("second policy sees reduced subtotal in chain", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(50), // 50% of 1000 = 500, remaining 500
          new PercentageDiscountPolicy(50), // 50% of 500 = 250, remaining 250
        ],
        "chain",
      );
      expect(composite.computeDiscountCents(1000)).toBe(750);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("chain cannot exceed subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new FixedAmountDiscountPolicy(600), // min(600, 1000) = 600, remaining 400
          new FixedAmountDiscountPolicy(600), // min(600, 400) = 400, remaining 0
        ],
        "chain",
      );
      expect(composite.computeDiscountCents(1000)).toBe(1000);
    });

    it("ordering matters in chain mode", () => {
      // Order 1: fixed first, then percentage
      const c1 = new CompositeDiscountPolicy(
        [
          new FixedAmountDiscountPolicy(200), // 200 off 1000 → remaining 800
          new PercentageDiscountPolicy(10), // 10% of 800 = 80
        ],
        "chain",
      );
      // Order 2: percentage first, then fixed
      const c2 = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10), // 10% of 1000 = 100 → remaining 900
          new FixedAmountDiscountPolicy(200), // 200 off 900 → 200
        ],
        "chain",
      );
      expect(c1.computeDiscountCents(1000)).toBe(280);
      expect(c2.computeDiscountCents(1000)).toBe(300);
    });
  });
});

import { describe, it, expect } from "vitest";
