describe("WeightBasedShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects empty brackets", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket is required",
      );
    });

    it("rejects bracket with non-positive upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 500 }]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with negative costCents", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 1000, costCents: -1 }]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer bracket values", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([{ upToGrams: 1.5, costCents: 500 }]),
      ).toThrow(RangeError);
      expect(
        () =>
          new WeightBasedShippingCalculator([{ upToGrams: 1000, costCents: 5.5 }]),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 500 }],
            -1,
          ),
      ).toThrow(RangeError);
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 500 }],
            10.5,
          ),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    const brackets = [
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 500 },
      { upToGrams: 5000, costCents: 800 },
    ];

    it("returns 0 for empty cart", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(calc.computeShippingCents([], 1000)).toBe(0);
    });

    it("returns 0 when total weight is 0", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      const lines = [makeLine("a", 1000, 1)]; // no weightGrams
      expect(calc.computeShippingCents(lines, 1000)).toBe(0);
    });

    it("selects first bracket for weight within range", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      const lines = [makeLine("a", 1000, 1, 300)]; // 300g → first bracket
      expect(calc.computeShippingCents(lines, 1000)).toBe(300);
    });

    it("selects bracket at exact boundary", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      const lines = [makeLine("a", 1000, 1, 500)]; // exactly 500g → first bracket
      expect(calc.computeShippingCents(lines, 1000)).toBe(300);
    });

    it("selects next bracket when weight exceeds boundary", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      const lines = [makeLine("a", 1000, 1, 501)]; // 501g → second bracket
      expect(calc.computeShippingCents(lines, 1000)).toBe(500);
    });

    it("selects third bracket for heavier items", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      const lines = [makeLine("a", 1000, 1, 2000)]; // 2000g → third bracket
      expect(calc.computeShippingCents(lines, 1000)).toBe(800);
    });

    it("uses overflow cost when weight exceeds all brackets", () => {
      const calc = new WeightBasedShippingCalculator(brackets, 1200);
      const lines = [makeLine("a", 1000, 1, 6000)]; // 6000g > 5000g
      expect(calc.computeShippingCents(lines, 1000)).toBe(1200);
    });

    it("uses heaviest bracket cost as fallback when no overflow specified", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      const lines = [makeLine("a", 1000, 1, 6000)]; // exceeds all brackets
      expect(calc.computeShippingCents(lines, 1000)).toBe(800);
    });

    it("sorts brackets regardless of input order", () => {
      const unordered = [
        { upToGrams: 5000, costCents: 800 },
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 1000, costCents: 500 },
      ];
      const calc = new WeightBasedShippingCalculator(unordered);
      const lines = [makeLine("a", 1000, 1, 300)]; // 300g → should hit 500g bracket
      expect(calc.computeShippingCents(lines, 1000)).toBe(300);
    });

    it("sums weight across multiple lines with quantity", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      const lines = [
        makeLine("a", 1000, 2, 200), // 200 * 2 = 400g
        makeLine("b", 500, 3, 100),  // 100 * 3 = 300g
      ]; // total = 700g → second bracket
      expect(calc.computeShippingCents(lines, 2000)).toBe(500);
    });
  });
});

