function makeProduct(
  id: string,
  unitPriceCents: number,
  weightGrams?: number,
): Product {
  return { id, name: id, unitPriceCents, weightGrams };
}

describe("Cart", () => {
  describe("add", () => {
    it("adds a product to the cart", () => {
      const cart = new Cart();
      cart.add(makeProduct("a", 1000), 2);
      expect(cart.itemCount).toBe(2);
    });

    it("merges quantities when adding the same product", () => {
      const cart = new Cart();
      cart.add(makeProduct("a", 1000), 2);
      cart.add(makeProduct("a", 1000), 3);
      expect(cart.itemCount).toBe(5);
    });

    it("tracks separate products independently", () => {
      const cart = new Cart();
      cart.add(makeProduct("a", 1000), 2);
      cart.add(makeProduct("b", 2000), 1);
      expect(cart.itemCount).toBe(3);
    });

    it("rejects zero quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(makeProduct("a", 1000), 0)).toThrow(RangeError);
    });

    it("rejects negative quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(makeProduct("a", 1000), -1)).toThrow(RangeError);
    });

    it("rejects non-integer quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(makeProduct("a", 1000), 1.5)).toThrow(RangeError);
    });

    it("rejects negative unitPriceCents", () => {
      const cart = new Cart();
      expect(() => cart.add(makeProduct("a", -100), 1)).toThrow(RangeError);
    });
  });

  describe("remove", () => {
    it("removes an existing product and returns true", () => {
      const cart = new Cart();
      cart.add(makeProduct("a", 1000), 1);
      expect(cart.remove("a")).toBe(true);
      expect(cart.itemCount).toBe(0);
    });

    it("returns false for unknown product id", () => {
      const cart = new Cart();
      expect(cart.remove("nonexistent")).toBe(false);
    });
  });

  describe("updateQuantity", () => {
    it("updates quantity for existing product", () => {
      const cart = new Cart();
      cart.add(makeProduct("a", 1000), 2);
      cart.updateQuantity("a", 5);
      expect(cart.itemCount).toBe(5);
    });

    it("removes product when quantity is set to 0", () => {
      const cart = new Cart();
      cart.add(makeProduct("a", 1000), 2);
      cart.updateQuantity("a", 0);
      expect(cart.itemCount).toBe(0);
    });

    it("throws for unknown product", () => {
      const cart = new Cart();
      expect(() => cart.updateQuantity("nonexistent", 1)).toThrow(
        "Product nonexistent is not in the cart",
      );
    });

    it("rejects negative quantity", () => {
      const cart = new Cart();
      cart.add(makeProduct("a", 1000), 1);
      expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
    });

    it("rejects non-integer quantity", () => {
      const cart = new Cart();
      cart.add(makeProduct("a", 1000), 1);
      expect(() => cart.updateQuantity("a", 1.5)).toThrow(RangeError);
    });
  });

  describe("clear", () => {
    it("removes all items", () => {
      const cart = new Cart();
      cart.add(makeProduct("a", 1000), 2);
      cart.add(makeProduct("b", 500), 3);
      cart.clear();
      expect(cart.itemCount).toBe(0);
    });
  });

  describe("snapshot", () => {
    it("returns a deep copy of cart lines", () => {
      const cart = new Cart();
      const product = makeProduct("a", 1000);
      cart.add(product, 2);
      const snap = cart.snapshot();
      expect(snap).toHaveLength(1);
      expect(snap[0]!.product.id).toBe("a");
      expect(snap[0]!.quantity).toBe(2);
      // Mutating the snapshot should not affect the cart
      (snap[0] as { quantity: number }).quantity = 99;
      expect(cart.itemCount).toBe(2);
    });
  });

  describe("totals - pricing pipeline", () => {
    it("computes subtotal as sum of unitPriceCents * quantity", () => {
      const cart = new Cart();
      cart.add(makeProduct("a", 1000), 2); // 2000
      cart.add(makeProduct("b", 500), 3);  // 1500
      const totals = cart.totals();
      expect(totals.subtotalCents).toBe(3500);
    });

    it("empty cart has all-zero totals", () => {
      const cart = new Cart();
      const totals = cart.totals();
      expect(totals).toEqual({
        subtotalCents: 0,
        discountCents: 0,
        taxCents: 0,
        shippingCents: 0,
        totalCents: 0,
      });
    });

    it("applies discount, then tax on discounted subtotal, then shipping", () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(200),
      };
      const taxCalculator: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(80),
      };
      const shippingCalculator: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(500),
      };

      const cart = new Cart({ discountPolicy, taxCalculator, shippingCalculator });
      cart.add(makeProduct("a", 1000), 1); // subtotal = 1000

      const totals = cart.totals();

      expect(totals.subtotalCents).toBe(1000);
      expect(totals.discountCents).toBe(200);
      // Tax is computed on discounted subtotal (1000 - 200 = 800)
      expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(800, "US");
      expect(totals.taxCents).toBe(80);
      // Shipping gets discounted subtotal
      expect(shippingCalculator.computeShippingCents).toHaveBeenCalledWith(
        expect.any(Array),
        800,
      );
      expect(totals.shippingCents).toBe(500);
      // total = discountedSubtotal + tax + shipping = 800 + 80 + 500
      expect(totals.totalCents).toBe(1380);
    });

    it("clamps discount to [0, subtotal]", () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(5000), // exceeds subtotal
      };
      const cart = new Cart({ discountPolicy });
      cart.add(makeProduct("a", 1000), 1);
      const totals = cart.totals();
      expect(totals.discountCents).toBe(1000); // clamped to subtotal
      expect(totals.totalCents).toBe(0);
    });

    it("clamps negative discount to 0", () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(-500),
      };
      const cart = new Cart({ discountPolicy });
      cart.add(makeProduct("a", 1000), 1);
      const totals = cart.totals();
      expect(totals.discountCents).toBe(0);
    });

    it("clamps negative tax to 0", () => {
      const taxCalculator: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(-100),
      };
      const cart = new Cart({ taxCalculator });
      cart.add(makeProduct("a", 1000), 1);
      const totals = cart.totals();
      expect(totals.taxCents).toBe(0);
    });

    it("clamps negative shipping to 0", () => {
      const shippingCalculator: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(-100),
      };
      const cart = new Cart({ shippingCalculator });
      cart.add(makeProduct("a", 1000), 1);
      const totals = cart.totals();
      expect(totals.shippingCents).toBe(0);
    });

    it("uses default region US", () => {
      const taxCalculator: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(0),
      };
      const cart = new Cart({ taxCalculator });
      cart.add(makeProduct("a", 1000), 1);
      cart.totals();
      expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(1000, "US");
    });

    it("uses custom region", () => {
      const taxCalculator: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(0),
      };
      const cart = new Cart({ taxCalculator, region: "FR" });
      cart.add(makeProduct("a", 1000), 1);
      cart.totals();
      expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(1000, "FR");
    });
  });

  describe("checkout", () => {
    let cart: Cart;

    beforeEach(() => {
      cart = new Cart();
      cart.add(makeProduct("prod-1", 1000), 2);
      cart.add(makeProduct("prod-2", 500), 1);
    });

    it("returns totals and lines without collaborators", async () => {
      const result = await cart.checkout();
      expect(result.totals.subtotalCents).toBe(2500);
      expect(result.lines).toHaveLength(2);
    });

    it("refreshes prices via priceFetcher", async () => {
      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi
          .fn()
          .mockResolvedValueOnce(1200) // prod-1 updated to 1200
          .mockResolvedValueOnce(600),  // prod-2 updated to 600
      };
      const result = await cart.checkout({ priceFetcher });
      // subtotal = 1200*2 + 600*1 = 3000
      expect(result.totals.subtotalCents).toBe(3000);
      expect(priceFetcher.fetchPriceCents).toHaveBeenCalledWith("prod-1");
      expect(priceFetcher.fetchPriceCents).toHaveBeenCalledWith("prod-2");
    });

    it("throws InventoryError when item is unavailable", async () => {
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: false, reason: "discontinued" }),
      };
      try {
        await cart.checkout({ inventoryChecker });
        expect.unreachable("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const invErr = err as InventoryError;
        expect(invErr.message).toBe("discontinued");
        expect(invErr.productId).toBe("prod-1");
        expect(invErr.requested).toBe(2);
      }
    });

    it("throws InventoryError for partial-stock denial", async () => {
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: true,
          availableQuantity: 1, // only 1 available but 2 requested
        }),
      };
      try {
        await cart.checkout({ inventoryChecker });
        expect.unreachable("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const invErr = err as InventoryError;
        expect(invErr.productId).toBe("prod-1");
        expect(invErr.requested).toBe(2);
        expect(invErr.available).toBe(1);
      }
    });

    it("generates default message for unavailable without reason", async () => {
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: false }),
      };
      try {
        await cart.checkout({ inventoryChecker });
        expect.unreachable("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        expect((err as InventoryError).message).toContain("insufficient stock");
      }
